using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
namespace AstroArchive {
 public static class UiHelp {
  public static void Tip(FrameworkElement control,string text){if(string.IsNullOrEmpty(text))return;control.ToolTip=new ToolTip{Content=new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,MaxWidth=360}};ToolTipService.SetShowOnDisabled(control,true);ToolTipService.SetShowDuration(control,20000);AutomationProperties.SetHelpText(control,text);}
  public static void For(FrameworkElement control,string label){string text;if(DialogTips.TryGetValue(label.TrimEnd('…','.'),out text))Tip(control,text);}
  static readonly Dictionary<string,string> DialogTips=new Dictionary<string,string>{
   {"Physical telescope ID","Name of the physical telescope for these captures. Use Rename telescope in Import to rename a saved device across the repository."},
   {"Camera channel","Telephoto or Wide. Leave blank to keep each capture's camera; separate channels use separate calibration groups."},
   {"Instrument model","Choose the known model, or Keep existing to preserve each capture's current metadata."},
   {"Frame type","Light, Stack, Dark, Flat or Bias; master calibration frames stay separate from individual calibration frames."},
   {"Mount mode","Assign EQ or Alt/Az when known. Unknown preserves uncertainty; rotation analysis provides evidence rather than certainty."},
   {"Calibration state","Describe processing already applied. Calibrated and registered lights do not receive additional calibration during export."},
   {"Exposure seconds (optional)","Exposure duration in seconds, using a decimal dot. Leave blank to keep existing values; zero is valid for bias frames."},
   {"Gain (optional)","Camera gain, using a decimal dot. Leave blank to keep existing values."},
   {"Sensor temperature °C (optional)","Sensor temperature in Celsius, using a decimal dot; negative values are allowed. Leave blank to keep existing values."},
